import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Limit, Meter, Resume } from '../types'

const empty: Meter = {
  tokens: null,
  window: 0,
  compactAt: null,
  growth: [],
  lastRequestAt: null,
  cacheRead: 0,
  cacheWrite: 0,
  uncached: 0,
  limits: [],
}

/** State kept by an older version survives a reload; fill in fields it lacks. */
export const current = (m: Partial<Meter> | null | undefined): Meter => {
  const known = Object.fromEntries(Object.entries(m ?? {}).filter(([, v]) => v !== undefined))
  return { ...empty, ...known }
}

const meter = atom({ plugin: 'context-meter', key: 'meter' } as const, empty)
const now = atom({ plugin: 'context-meter', key: 'now' } as const, 0)
const warned = atom({ plugin: 'context-meter', key: 'warned' } as const, false)
const resume = atom({ plugin: 'context-meter', key: 'resume' } as const, null as Resume | null)
/** `<kind>:<threshold>:<reset>` already toasted, so each crossing warns once per window. */
const limitWarned = atom({ plugin: 'context-meter', key: 'limitWarned' } as const, [] as string[])

const WARN_MS = 5 * 60_000
/** Below this a cold re-cache is cheap enough not to hold the first message. */
const GUARD_TOKENS = 50_000
/** Turns left and hit rate only earn their place below these. */
const SHOW_TURNS_BELOW = 30
const SHOW_HIT_BELOW = 0.8
const LIMIT_THRESHOLDS = [80, 95]

// Claude Code theme keys, so the band follows /theme.
const DIM = 'inactive'
const ACCENT = 'claude'
const WARN = 'warning'
const ERR = 'error'

const k = (n: number) => (n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : `${Math.round(n / 1000)}k`)

const duration = (ms: number) => {
  const m = Math.ceil(ms / 60_000)
  return m >= 60 ? `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m` : `${m}m`
}

const usd = (n: number | null) => (n === null ? '' : ` (~$${n.toFixed(2)})`)

const severity = (fraction: number) => (fraction >= 0.9 ? ERR : fraction >= 0.75 ? WARN : undefined)

const LIMIT_LABEL: Record<string, string> = { five_hour: '5h', seven_day: 'week', spend_limit: 'spend' }

/** Reset time as the person reads it: a clock time within the day, a weekday further out. */
export const resetLabel = (iso: string | undefined, t: number): string => {
  if (!iso) return ''
  const at = new Date(iso)
  if (Number.isNaN(at.getTime())) return ''
  const hm = `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`
  if (at.getTime() - t < 20 * 3600_000) return hm
  return `${['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][at.getDay()]} ${hm}`
}

/** Turns left before auto-compaction, from the average growth of the last few turns. */
export const turnsLeft = (m: Meter): number | null => {
  if (m.tokens === null || m.compactAt === null) return null
  const recent = m.growth.slice(-5)
  if (recent.length === 0) return null
  const avg = recent.reduce((a, b) => a + b, 0) / recent.length
  if (avg <= 0) return null
  return Math.max(0, Math.floor((m.compactAt - m.tokens) / avg))
}

export const hitRate = (m: Meter): number | null => {
  const total = m.cacheRead + m.cacheWrite + m.uncached
  return total === 0 ? null : m.cacheRead / total
}

/** Reads the auto-compact threshold from the locally estimated /context breakdown (no API request). */
async function refreshCompactAt($: EngineInterface) {
  try {
    const { context, rateLimits } = await $.session.usage({ breakdown: 'summary' })
    const threshold = context.breakdown?.isAutoCompactEnabled ? context.breakdown.autoCompactThreshold : undefined
    await update($, meter, old => {
      const m = current(old)
      return { ...m, window: context.window, compactAt: threshold ?? null, limits: rateLimits.length > 0 ? rateLimits : m.limits }
    })
  } catch {
    // No session bound yet; the next measurement retries.
  }
}

/** Toasts once per window when a usage limit crosses 80% and 95%. */
async function warnLimits($: EngineInterface, limits: readonly Limit[]) {
  const seen = await read($, limitWarned)
  const t = await $.clock.now()
  const fresh: string[] = []
  for (const limit of limits) {
    const crossed = LIMIT_THRESHOLDS.filter(x => limit.percentUsed >= x).pop()
    if (crossed === undefined) continue
    const id = `${limit.kind}:${crossed}:${limit.resetsAt ?? ''}`
    if (seen.includes(id)) continue
    fresh.push(id)
    const label = LIMIT_LABEL[limit.kind] ?? limit.kind
    const reset = resetLabel(limit.resetsAt, t)
    $.ui.toast(`${label} usage at ${Math.round(limit.percentUsed)}%${reset ? `, resets ${reset}` : ''}`)
  }
  if (fresh.length > 0) await update($, limitWarned, list => [...list, ...fresh].slice(-20))
}

/** Compacting reads the cold context once, then later messages stay small. */
async function compactNow($: EngineInterface) {
  await update($, resume, () => null)
  await $.session.compact()
}

export const register: Register = (on, options) => {
  const ttlMs = Number(options.cacheTtlMinutes ?? '60') * 60_000
  const isGuarding = options.resumeGuard !== false

  // A resume reports the old context and how long it sat; show both before the first message.
  on('classic.SessionStart', async ($, e, next) => {
    if ((e.source === 'resume' || e.source === 'fork') && e.context_tokens) {
      const t = await $.clock.now()
      const idleMs = (e.seconds_since_last_response ?? 0) * 1000
      const tokens = e.context_tokens
      await update($, now, () => t)
      await update($, meter, old => ({ ...current(old), tokens, growth: [], lastRequestAt: t - idleMs }))
      void refreshCompactAt($)
      if (e.prompt_cache_likely_expired) {
        const isHeld = isGuarding && tokens >= GUARD_TOKENS
        await update($, resume, () => ({ tokens, idleMs, usd: e.estimated_cache_write_usd ?? null, isHeld }))
      }
    }

    return next(e)
  })

  // Hold the first prompt once when it would re-cache a big cold context.
  on('prompt.submit', async ($, e, next) => {
    const r = await read($, resume)
    if (!r?.isHeld || e.origin || e.text.trimStart().startsWith('/')) return next(e)
    await update($, resume, x => (x ? { ...x, isHeld: false } : x))

    return {
      drop:
        `Prompt cache is cold (idle ${duration(r.idleMs)}): this message would re-cache ${k(r.tokens)} tokens${usd(r.usd)}. ` +
        'Send it again to go ahead, or /compact or start a new session first.',
    }
  })

  on('session.start', async ($, e, next) => {
    await update($, now, () => 0)
    void refreshCompactAt($)
    $.clock.every(15_000, async () => {
      const t = await $.clock.now()
      await update($, now, () => t)
      const m = current(await read($, meter))
      if (m.lastRequestAt === null) return
      const left = m.lastRequestAt + ttlMs - t
      if (left > 0 && left <= WARN_MS && !(await read($, warned))) {
        await update($, warned, () => true)
        $.ui.toast(`Prompt cache expires in ${duration(left)}: send something to keep it warm`)
      }
    })

    return next(e)
  })

  // Every model request rewrites the cache's expiry and reports cache usage.
  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    const usage = result.usage
    if (usage) {
      const t = await $.clock.now()
      await update($, warned, () => false)
      await update($, resume, () => null)
      await update($, now, () => t)
      await update($, meter, old => ({
        ...current(old),
        lastRequestAt: t,
        cacheRead: usage.cache_read_input_tokens,
        cacheWrite: usage.cache_creation_input_tokens,
        uncached: usage.input_tokens,
      }))
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    const tokens = e.context.tokens ?? null
    await update($, meter, old => {
      const m = current(old)
      const delta = tokens !== null && m.tokens !== null ? tokens - m.tokens : 0
      return {
        ...m,
        tokens: tokens ?? m.tokens,
        window: e.context.window,
        // A drop means a compaction or /clear: start the growth average over.
        growth: delta < 0 ? [] : delta > 0 ? [...m.growth, delta].slice(-10) : m.growth,
        limits: e.rateLimits.length > 0 ? e.rateLimits : m.limits,
      }
    })
    if (e.changed.includes('context')) void refreshCompactAt($)
    if (e.changed.includes('rateLimits')) await warnLimits($, e.rateLimits)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const m = current(await read($, meter))
    if (e.props.hasSurvey || (m.tokens === null && m.limits.length === 0)) return next(e)

    const { Box, Button, Text } = $.ui.resolve(e)
    const t = (await read($, now)) || (await $.clock.now())
    const r = await read($, resume)

    // Context: a slim line, accent-filled, warning colours near the compact point.
    const limit = m.compactAt ?? (m.window || null)
    const fill = m.tokens === null || limit === null ? null : m.tokens / limit
    const width = 12
    const filled = fill === null ? 0 : Math.max(0, Math.min(width, Math.round(fill * width)))
    const turns = turnsLeft(m)

    // Cache: just the time left; the hit rate only when it is poor.
    const rate = hitRate(m)
    const cacheLeft = m.lastRequestAt === null ? null : m.lastRequestAt + ttlMs - t

    const context =
      m.tokens === null ? null : (
        <Box key="context">
          <Text color={DIM}>context </Text>
          {fill !== null && <Text color={severity(fill) ?? ACCENT}>{'━'.repeat(filled)}</Text>}
          {fill !== null && <Text color={DIM}>{'─'.repeat(width - filled)} </Text>}
          {fill !== null && <Text color={severity(fill) ?? DIM}>{Math.round(fill * 100)}%</Text>}
          <Text color={DIM}>
            {fill !== null ? ' ' : ''}
            {k(m.tokens)}
            {limit !== null ? `/${k(limit)}` : ''}
          </Text>
          {turns !== null && turns < SHOW_TURNS_BELOW && (
            <Text color={turns < 5 ? ERR : WARN}> ~{turns} turns to compact</Text>
          )}
        </Box>
      )

    const cache =
      cacheLeft === null ? null : (
        <Box key="cache">
          <Text color={DIM}>cache </Text>
          {cacheLeft <= 0 ? (
            <Text color={ERR}>cold · next message re-reads {k(m.tokens ?? 0)}</Text>
          ) : (
            <Text color={cacheLeft <= WARN_MS ? WARN : DIM}>{duration(cacheLeft)}</Text>
          )}
          {cacheLeft > 0 && rate !== null && rate < SHOW_HIT_BELOW && (
            <Text color={WARN}> {Math.round(rate * 100)}% hit</Text>
          )}
        </Box>
      )

    const usage =
      m.limits.length === 0 ? null : (
        <Box key="usage">
          <Text color={DIM}>usage </Text>
          {m.limits.map((l, i) => {
            const reset = resetLabel(l.resetsAt, t)
            return (
              <Box key={l.kind}>
                <Text color={DIM}>
                  {i > 0 ? ' · ' : ''}
                  {LIMIT_LABEL[l.kind] ?? l.kind}{' '}
                </Text>
                <Text color={severity(l.percentUsed / 100) ?? DIM}>{Math.round(l.percentUsed)}%</Text>
                {reset !== '' && <Text color={DIM}> ↻ {reset}</Text>}
              </Box>
            )
          })}
        </Box>
      )

    const parts = [context, cache, usage].filter(x => x !== null)
    const row = (
      <Box>
        {parts.map((part, i) => (
          <Box key={`part-${i}`}>
            {i > 0 && <Text color={DIM}> · </Text>}
            {part}
          </Box>
        ))}
      </Box>
    )

    if (r === null) return row

    return (
      <Box flexDirection="column">
        <Box>
          <Text color={WARN}>
            Resumed {k(r.tokens)} after {duration(r.idleMs)} idle · cache expired, next message re-caches it{usd(r.usd)}
            {r.isHeld ? ' · first send is held once' : ''}{' '}
          </Text>
          <Button key="compact" label="Compact" onPress={() => compactNow($)} />
          <Text> </Text>
          <Button key="dismiss" label="Dismiss" onPress={() => update($, resume, () => null)} />
        </Box>
        {row}
      </Box>
    )
  })
}

