{
  "name": "context-meter",
  "version": "0.3.1",
  "description": "Band above the prompt: context fill, prompt-cache countdown, usage limits, and a guard for resuming cold sessions",
  "types": "./types/index.d.ts",
  "userConfig": {
    "cacheTtlMinutes": {
      "type": "string",
      "title": "Prompt cache TTL (minutes)",
      "description": "How long the prompt cache lives after the last request: 60 on the 1-hour cache, 5 on the default/overage cache",
      "default": "60",
      "options": [
        "60",
        "5"
      ]
    },
    "resumeGuard": {
      "type": "boolean",
      "title": "Resume guard",
      "description": "On resuming a big session whose prompt cache expired, hold the first message once and show the re-cache cost",
      "default": true
    }
  },
  "author": {
    "name": "Yassin Rezai"
  }
}

