export type Meter = {
  /** Input tokens of the last response (uncached + cache read + cache write). */
  tokens: number | null
  window: number
  /** Token count where auto-compaction runs; null when off or unknown. */
  compactAt: number | null
  /** Context growth per turn, most recent last. */
  growth: number[]
  /** When the last model request refreshed the cache, clock ms; null before one. */
  lastRequestAt: number | null
  cacheRead: number
  cacheWrite: number
  uncached: number
  /** Account usage windows (five_hour, seven_day, ...), as the last response reported them. */
  limits: Limit[]
}

export type Limit = { kind: string; percentUsed: number; resetsAt?: string }

/** A resumed session whose cache had expired: what its first message would re-cache. */
export type Resume = {
  tokens: number
  idleMs: number
  usd: number | null
  /** True until the person sends anyway, compacts, or a request goes through. */
  isHeld: boolean
}

declare module 'claude-code' {
  interface PluginState {
    'context-meter': { meter: Meter; now: number; warned: boolean; resume: Resume | null; limitWarned: string[] }
  }
}
